-- 图趴 PicParty 1.0 Beta consolidated Supabase schema
create extension if not exists pgcrypto;

create table if not exists public.profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 username text unique not null,
 display_name text,
 avatar_url text,
 bio text,
 onboarding_completed boolean not null default false,
 website_url text,
 location_text text,
 preferred_language text not null default 'en',
 preferred_timezone text not null default 'UTC',
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 constraint profiles_language check(preferred_language in ('zh-Hans','zh-Hant','en','fr','ja','ko','es')),
 constraint profiles_username_len check(char_length(trim(username)) between 3 and 30),
 constraint profiles_username_format check(username ~ '^[a-z0-9_.]+$'),
 constraint profiles_bio_len check(bio is null or char_length(bio)<=500)
);

create table if not exists public.parties (
 id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade,
 title text not null, description text, category text, content_language text not null default 'en', cover_media_url text, cover_storage_path text,
 countdown_style text not null default 'digital', privacy text not null default 'public', start_at timestamptz not null, end_at timestamptz not null,
 status text not null default 'live', client_request_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), last_activity_at timestamptz not null default now(),
 constraint parties_title_len check(char_length(trim(title)) between 1 and 80), constraint parties_description_len check(description is null or char_length(description)<=500),
 constraint parties_time_valid check(end_at>start_at), constraint parties_duration check(end_at-start_at<=interval '30 days'),
 constraint parties_privacy check(privacy in ('public','unlisted','private')),
 constraint parties_status check(status in ('draft','scheduled','live','ended','deleting')),
 constraint parties_countdown check(countdown_style in ('digital','motor','rock','gothic','sweet','cartoon','dream','cinema','flip','minimal','festival','cyber')),
 constraint parties_language check(content_language in ('zh-Hans','zh-Hant','en','fr','ja','ko','es'))
);
create unique index if not exists parties_owner_client_request_unique on public.parties(owner_id,client_request_id) where client_request_id is not null;
create index if not exists parties_live_idx on public.parties(status,last_activity_at desc) where privacy='public';
create index if not exists parties_owner_idx on public.parties(owner_id,created_at desc);

create table if not exists public.party_members (
 party_id uuid references public.parties(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade,
 role text not null default 'member', status text not null default 'active', invited_by uuid references public.profiles(id) on delete set null,
 joined_at timestamptz not null default now(), primary key(party_id,user_id),
 constraint party_member_role check(role in ('owner','member')), constraint party_member_status check(status in ('active','invited','declined','removed'))
);
create index if not exists party_members_user_idx on public.party_members(user_id,status);

create table if not exists public.media_posts (
 id uuid primary key default gen_random_uuid(), party_id uuid not null references public.parties(id) on delete cascade,
 user_id uuid not null references public.profiles(id) on delete cascade, media_type text not null, original_storage_path text,
 feed_storage_path text, full_storage_path text, poster_storage_path text, processing_status text not null default 'uploading',
 file_size bigint, mime_type text, caption text, like_count integer not null default 0, comment_count integer not null default 0,
 created_at timestamptz not null default now(), constraint media_type_check check(media_type in ('image','video')),
 constraint media_status_check check(processing_status in ('uploading','processing','ready','failed')),
 constraint media_caption_len check(caption is null or char_length(caption)<=1000)
);
create index if not exists media_party_idx on public.media_posts(party_id,created_at desc);
create index if not exists media_user_idx on public.media_posts(user_id,created_at desc);

create table if not exists public.likes(id uuid primary key default gen_random_uuid(),media_id uuid references public.media_posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(media_id,user_id));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),media_id uuid references public.media_posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,parent_id uuid references public.comments(id) on delete cascade,reply_to_user_id uuid references public.profiles(id) on delete set null,content text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint comments_len check(char_length(trim(content)) between 1 and 500));
create index if not exists comments_media_idx on public.comments(media_id,created_at desc);

create table if not exists public.follows(id uuid primary key default gen_random_uuid(),follower_id uuid references public.profiles(id) on delete cascade,following_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(follower_id,following_id),constraint follows_not_self check(follower_id<>following_id));
create table if not exists public.blocked_users(blocker_id uuid references public.profiles(id) on delete cascade,blocked_user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_user_id),constraint blocked_not_self check(blocker_id<>blocked_user_id));

create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),user_a_id uuid references public.profiles(id) on delete cascade,user_b_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint conversations_not_self check(user_a_id<>user_b_id));
create unique index if not exists conversations_pair_unique on public.conversations(least(user_a_id,user_b_id),greatest(user_a_id,user_b_id));
create table if not exists public.conversation_members(conversation_id uuid references public.conversations(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,last_read_at timestamptz,joined_at timestamptz not null default now(),primary key(conversation_id,user_id));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid references public.conversations(id) on delete cascade,sender_id uuid references public.profiles(id) on delete cascade,content text not null,client_message_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,constraint messages_len check(char_length(trim(content)) between 1 and 2000),unique(conversation_id,client_message_id));

create table if not exists public.party_invites(id uuid primary key default gen_random_uuid(),party_id uuid references public.parties(id) on delete cascade,inviter_id uuid references public.profiles(id) on delete cascade,invitee_id uuid references public.profiles(id) on delete cascade,status text not null default 'pending',created_at timestamptz not null default now(),responded_at timestamptz,expires_at timestamptz,constraint invite_status check(status in ('pending','accepted','declined','cancelled','expired')));
create unique index if not exists party_pending_invite_unique on public.party_invites(party_id,invitee_id) where status='pending';

create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid references public.profiles(id) on delete cascade,actor_id uuid references public.profiles(id) on delete set null,type text not null,party_id uuid references public.parties(id) on delete cascade,media_id uuid references public.media_posts(id) on delete cascade,comment_id uuid references public.comments(id) on delete cascade,conversation_id uuid references public.conversations(id) on delete cascade,invite_id uuid references public.party_invites(id) on delete cascade,title text,body text,is_read boolean not null default false,created_at timestamptz not null default now());
create index if not exists notifications_recipient_idx on public.notifications(recipient_id,created_at desc);

create table if not exists public.party_translations(id uuid primary key default gen_random_uuid(),party_id uuid references public.parties(id) on delete cascade,language_code text not null,title text not null,description text,translation_status text not null default 'ready',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(party_id,language_code));
create table if not exists public.comment_translations(id uuid primary key default gen_random_uuid(),comment_id uuid references public.comments(id) on delete cascade,language_code text not null,translated_content text not null,translation_status text not null default 'ready',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(comment_id,language_code));
create table if not exists public.user_devices(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,platform text not null,push_token text not null,app_version text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,push_token));
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references public.profiles(id) on delete cascade,reported_user_id uuid references public.profiles(id) on delete cascade,party_id uuid references public.parties(id) on delete cascade,media_id uuid references public.media_posts(id) on delete cascade,comment_id uuid references public.comments(id) on delete cascade,reason text not null,description text,status text not null default 'pending',created_at timestamptz not null default now(),reviewed_at timestamptz,reviewed_by uuid references public.profiles(id) on delete set null,admin_note text);

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
declare base text; begin base=lower(regexp_replace(coalesce(new.raw_user_meta_data->>'user_name','user'),'[^a-zA-Z0-9_.]','','g')); if char_length(base)<3 then base='user_'||substr(new.id::text,1,8); end if; insert into public.profiles(id,username,display_name) values(new.id,base,new.raw_user_meta_data->>'display_name') on conflict(id) do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

create or replace function public.users_are_blocked(a uuid,b uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from blocked_users where (blocker_id=a and blocked_user_id=b) or (blocker_id=b and blocked_user_id=a)); $$;
create or replace function public.can_view_party(pid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from parties p where p.id=pid and p.status<>'deleting' and (p.privacy='public' or p.owner_id=auth.uid() or exists(select 1 from party_members pm where pm.party_id=p.id and pm.user_id=auth.uid() and pm.status='active')) and not users_are_blocked(auth.uid(),p.owner_id)); $$;
create or replace function public.party_is_live(pid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from parties where id=pid and status='live' and now()<end_at and now()>=start_at); $$;

create or replace function public.create_party(p_title text,p_description text default null,p_category text default null,p_content_language text default 'en',p_cover_storage_path text default null,p_countdown_style text default 'digital',p_privacy text default 'public',p_start_at timestamptz default null,p_duration_minutes integer default 60,p_client_request_id uuid default null) returns public.parties language plpgsql security definer set search_path=public as $$
declare r public.parties;s timestamptz;e timestamptz;begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;if p_client_request_id is not null then select * into r from parties where owner_id=auth.uid() and client_request_id=p_client_request_id limit 1;if found then return r;end if;end if;if char_length(trim(p_title)) not between 1 and 80 then raise exception 'INVALID_TITLE';end if;if p_duration_minutes not between 1 and 43200 then raise exception 'INVALID_DURATION';end if;s=coalesce(p_start_at,now());if s<now() then s=now();end if;e=s+make_interval(mins=>p_duration_minutes);insert into parties(owner_id,title,description,category,content_language,cover_storage_path,countdown_style,privacy,start_at,end_at,status,client_request_id) values(auth.uid(),trim(p_title),nullif(trim(p_description),''),p_category,p_content_language,p_cover_storage_path,p_countdown_style,p_privacy,s,e,case when s<=now() then 'live' else 'scheduled' end,p_client_request_id) returning * into r;insert into party_members(party_id,user_id,role,status) values(r.id,auth.uid(),'owner','active');return r;end $$;
grant execute on function public.create_party(text,text,text,text,text,text,text,timestamptz,integer,uuid) to authenticated;

create or replace function public.join_party(pid uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;if not exists(select 1 from parties where id=pid and status<>'deleting' and ((privacy='public') or (privacy='unlisted'))) then raise exception 'NOT_JOINABLE';end if;if users_are_blocked(auth.uid(),(select owner_id from parties where id=pid)) then raise exception 'BLOCKED';end if;insert into party_members(party_id,user_id,role,status) values(pid,auth.uid(),'member','active') on conflict(party_id,user_id) do update set status='active';return true;end $$;
grant execute on function public.join_party(uuid) to authenticated;

create or replace function public.create_media_post(p_id uuid,p_party_id uuid,p_media_type text,p_original_storage_path text,p_file_size bigint,p_mime_type text,p_caption text default null) returns public.media_posts language plpgsql security definer set search_path=public as $$
declare r public.media_posts;begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;if not party_is_live(p_party_id) then raise exception 'PARTY_NOT_LIVE';end if;if not exists(select 1 from party_members where party_id=p_party_id and user_id=auth.uid() and status='active') then raise exception 'NOT_MEMBER';end if;if users_are_blocked(auth.uid(),(select owner_id from parties where id=p_party_id)) then raise exception 'BLOCKED';end if;if p_file_size<=0 or (p_media_type='image' and p_file_size>20971520) or (p_media_type='video' and p_file_size>209715200) then raise exception 'FILE_TOO_LARGE';end if;insert into media_posts(id,party_id,user_id,media_type,original_storage_path,file_size,mime_type,caption,processing_status) values(p_id,p_party_id,auth.uid(),p_media_type,p_original_storage_path,p_file_size,p_mime_type,p_caption,'uploading') returning * into r;return r;end $$;
grant execute on function public.create_media_post(uuid,uuid,text,text,bigint,text,text) to authenticated;
create or replace function public.media_upload_completed(mid uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin update media_posts set processing_status='processing' where id=mid and user_id=auth.uid() and processing_status='uploading';return found;end $$;grant execute on function public.media_upload_completed(uuid) to authenticated;

create or replace function public.like_media(mid uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare owner_id uuid;begin if not exists(select 1 from media_posts m where m.id=mid and m.processing_status='ready' and can_view_party(m.party_id)) then raise exception 'NOT_VIEWABLE';end if;insert into likes(media_id,user_id) values(mid,auth.uid()) on conflict do nothing;update media_posts set like_count=(select count(*) from likes where media_id=mid) where id=mid;select user_id into owner_id from media_posts where id=mid;if owner_id<>auth.uid() then insert into notifications(recipient_id,actor_id,type,media_id) values(owner_id,auth.uid(),'like',mid);end if;return true;end $$;grant execute on function public.like_media(uuid) to authenticated;
create or replace function public.unlike_media(mid uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin delete from likes where media_id=mid and user_id=auth.uid();update media_posts set like_count=(select count(*) from likes where media_id=mid) where id=mid;return true;end $$;grant execute on function public.unlike_media(uuid) to authenticated;

create or replace function public.create_comment(p_media_id uuid,p_content text,p_parent_id uuid default null,p_reply_to_user_id uuid default null) returns public.comments language plpgsql security definer set search_path=public as $$ declare r public.comments;owner_id uuid;begin if char_length(trim(p_content)) not between 1 and 500 then raise exception 'INVALID_COMMENT';end if;if not exists(select 1 from media_posts m where m.id=p_media_id and m.processing_status='ready' and can_view_party(m.party_id)) then raise exception 'NOT_VIEWABLE';end if;if p_parent_id is not null and exists(select 1 from comments where id=p_parent_id and parent_id is not null) then raise exception 'MAX_REPLY_DEPTH';end if;insert into comments(media_id,user_id,parent_id,reply_to_user_id,content) values(p_media_id,auth.uid(),p_parent_id,p_reply_to_user_id,trim(p_content)) returning * into r;update media_posts set comment_count=(select count(*) from comments where media_id=p_media_id) where id=p_media_id;select user_id into owner_id from media_posts where id=p_media_id;if owner_id<>auth.uid() then insert into notifications(recipient_id,actor_id,type,media_id,comment_id) values(coalesce(p_reply_to_user_id,owner_id),auth.uid(),case when p_parent_id is null then 'comment' else 'reply' end,p_media_id,r.id);end if;return r;end $$;grant execute on function public.create_comment(uuid,text,uuid,uuid) to authenticated;

create or replace function public.follow_user(pid uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin if pid=auth.uid() then raise exception 'SELF_FOLLOW';end if;if users_are_blocked(auth.uid(),pid) then raise exception 'BLOCKED';end if;insert into follows(follower_id,following_id) values(auth.uid(),pid) on conflict do nothing;insert into notifications(recipient_id,actor_id,type) values(pid,auth.uid(),'follow');return true;end $$;grant execute on function public.follow_user(uuid) to authenticated;
create or replace function public.unfollow_user(pid uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin delete from follows where follower_id=auth.uid() and following_id=pid;return true;end $$;grant execute on function public.unfollow_user(uuid) to authenticated;
create or replace function public.block_user(pid uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin if pid=auth.uid() then raise exception 'SELF_BLOCK';end if;insert into blocked_users values(auth.uid(),pid) on conflict do nothing;delete from follows where (follower_id=auth.uid() and following_id=pid) or (follower_id=pid and following_id=auth.uid());return true;end $$;grant execute on function public.block_user(uuid) to authenticated;
create or replace function public.unblock_user(pid uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin delete from blocked_users where blocker_id=auth.uid() and blocked_user_id=pid;return true;end $$;grant execute on function public.unblock_user(uuid) to authenticated;

create or replace function public.get_or_create_conversation(pid uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare cid uuid; a uuid; b uuid;begin if pid=auth.uid() or users_are_blocked(auth.uid(),pid) then raise exception 'CHAT_NOT_ALLOWED';end if;a=least(auth.uid(),pid);b=greatest(auth.uid(),pid);select id into cid from conversations where user_a_id=a and user_b_id=b; if cid is null then insert into conversations(user_a_id,user_b_id) values(a,b) returning id into cid;insert into conversation_members values(cid,auth.uid(),null), (cid,pid,null);end if;return cid;end $$;grant execute on function public.get_or_create_conversation(uuid) to authenticated;
create or replace function public.send_message(cid uuid,body text,client_id uuid) returns public.messages language plpgsql security definer set search_path=public as $$ declare r public.messages;other uuid;begin if not exists(select 1 from conversation_members where conversation_id=cid and user_id=auth.uid()) then raise exception 'NOT_MEMBER';end if;if char_length(trim(body)) not between 1 and 2000 then raise exception 'INVALID_MESSAGE';end if;select case when user_a_id=auth.uid() then user_b_id else user_a_id end into other from conversations where id=cid;if users_are_blocked(auth.uid(),other) then raise exception 'BLOCKED';end if;select * into r from messages where conversation_id=cid and client_message_id=client_id;if found then return r;end if;insert into messages(conversation_id,sender_id,content,client_message_id) values(cid,auth.uid(),trim(body),client_id) returning * into r;update conversations set updated_at=now() where id=cid;insert into notifications(recipient_id,actor_id,type,conversation_id) values(other,auth.uid(),'message',cid);return r;end $$;grant execute on function public.send_message(uuid,text,uuid) to authenticated;
create or replace function public.mark_conversation_read(cid uuid) returns boolean language sql security definer set search_path=public as $$ update conversation_members set last_read_at=now() where conversation_id=cid and user_id=auth.uid();select true; $$;grant execute on function public.mark_conversation_read(uuid) to authenticated;

create or replace function public.create_party_invite(pid uuid,invitee uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare iid uuid;begin if not exists(select 1 from parties where id=pid and owner_id=auth.uid() and privacy='private' and status not in ('ended','deleting')) then raise exception 'NOT_ALLOWED';end if;if users_are_blocked(auth.uid(),invitee) then raise exception 'BLOCKED';end if;select id into iid from party_invites where party_id=pid and invitee_id=invitee and status='pending';if iid is null then insert into party_invites(party_id,inviter_id,invitee_id) values(pid,auth.uid(),invitee) returning id into iid;end if;insert into notifications(recipient_id,actor_id,type,party_id,invite_id) values(invitee,auth.uid(),'party_invite',pid,iid);return iid;end $$;grant execute on function public.create_party_invite(uuid,uuid) to authenticated;
create or replace function public.accept_party_invite(iid uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare pid uuid;begin select party_id into pid from party_invites where id=iid and invitee_id=auth.uid() and status='pending';if pid is null then raise exception 'INVALID_INVITE';end if;if exists(select 1 from party_members where party_id=pid and user_id=auth.uid() and status='removed') then raise exception 'REMOVED';end if;insert into party_members(party_id,user_id,role,status) values(pid,auth.uid(),'member','active') on conflict(party_id,user_id) do update set status='active';update party_invites set status='accepted',responded_at=now() where id=iid;return true;end $$;grant execute on function public.accept_party_invite(uuid) to authenticated;

create or replace function public.get_discover_live(lim integer default 20,before_at timestamptz default null) returns setof public.parties language sql stable security definer set search_path=public as $$ select p from parties p where p.privacy='public' and p.status='live' and (before_at is null or p.last_activity_at<before_at) and not users_are_blocked(auth.uid(),p.owner_id) order by p.last_activity_at desc limit least(greatest(lim,1),50); $$;grant execute on function public.get_discover_live(integer,timestamptz) to authenticated;
create or replace function public.search_parties(q text,lim integer default 20) returns setof public.parties language sql stable security definer set search_path=public as $$ select p from parties p where p.privacy='public' and p.status='live' and (p.title ilike '%'||q||'%' or coalesce(p.description,'') ilike '%'||q||'%' or coalesce(p.category,'') ilike '%'||q||'%') and not users_are_blocked(auth.uid(),p.owner_id) order by p.last_activity_at desc limit least(greatest(lim,1),50); $$;grant execute on function public.search_parties(text,integer) to authenticated;

create or replace function public.get_notifications(lim integer default 50) returns setof public.notifications language sql stable security definer set search_path=public as $$ select * from notifications where recipient_id=auth.uid() order by created_at desc limit least(greatest(lim,1),100); $$;grant execute on function public.get_notifications(integer) to authenticated;
create or replace function public.mark_all_notifications_read() returns boolean language sql security definer set search_path=public as $$ update notifications set is_read=true where recipient_id=auth.uid();select true; $$;grant execute on function public.mark_all_notifications_read() to authenticated;

create or replace function public.update_my_profile(p_username text,p_display_name text,p_bio text,p_website_url text,p_location_text text,p_preferred_language text,p_preferred_timezone text) returns public.profiles language plpgsql security definer set search_path=public as $$ declare r public.profiles;begin if p_preferred_language not in ('zh-Hans','zh-Hant','en','fr','ja','ko','es') then raise exception 'INVALID_LANGUAGE';end if;update profiles set username=lower(trim(p_username)),display_name=nullif(trim(p_display_name),''),bio=nullif(trim(p_bio),''),website_url=nullif(trim(p_website_url),''),location_text=nullif(trim(p_location_text),''),preferred_language=p_preferred_language,preferred_timezone=p_preferred_timezone,updated_at=now() where id=auth.uid() returning * into r;return r;end $$;grant execute on function public.update_my_profile(text,text,text,text,text,text,text) to authenticated;

alter table public.profiles enable row level security;alter table public.parties enable row level security;alter table public.party_members enable row level security;alter table public.media_posts enable row level security;alter table public.likes enable row level security;alter table public.comments enable row level security;alter table public.follows enable row level security;alter table public.blocked_users enable row level security;alter table public.conversations enable row level security;alter table public.conversation_members enable row level security;alter table public.messages enable row level security;alter table public.notifications enable row level security;alter table public.party_invites enable row level security;alter table public.reports enable row level security;

drop policy if exists profiles_public_select on public.profiles;create policy profiles_public_select on public.profiles for select to authenticated using(true);
drop policy if exists parties_public_select on public.parties;create policy parties_public_select on public.parties for select to authenticated using(privacy='public' or owner_id=auth.uid() or exists(select 1 from party_members pm where pm.party_id=parties.id and pm.user_id=auth.uid() and pm.status='active'));
drop policy if exists members_select on public.party_members;create policy members_select on public.party_members for select to authenticated using(user_id=auth.uid() or exists(select 1 from parties p where p.id=party_members.party_id and p.owner_id=auth.uid()));
drop policy if exists media_select on public.media_posts;create policy media_select on public.media_posts for select to authenticated using(can_view_party(party_id));
drop policy if exists likes_select on public.likes;create policy likes_select on public.likes for select to authenticated using(can_view_party((select party_id from media_posts where id=likes.media_id)));
drop policy if exists comments_select on public.comments;create policy comments_select on public.comments for select to authenticated using(can_view_party((select party_id from media_posts where id=comments.media_id)));
drop policy if exists follows_select on public.follows;create policy follows_select on public.follows for select to authenticated using(true);
drop policy if exists blocked_select on public.blocked_users;create policy blocked_select on public.blocked_users for select to authenticated using(blocker_id=auth.uid());
drop policy if exists conversations_select on public.conversations;create policy conversations_select on public.conversations for select to authenticated using(user_a_id=auth.uid() or user_b_id=auth.uid());
drop policy if exists conversation_members_select on public.conversation_members;create policy conversation_members_select on public.conversation_members for select to authenticated using(user_id=auth.uid());
drop policy if exists messages_select on public.messages;create policy messages_select on public.messages for select to authenticated using(exists(select 1 from conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));
drop policy if exists notifications_select on public.notifications;create policy notifications_select on public.notifications for select to authenticated using(recipient_id=auth.uid());
drop policy if exists invites_select on public.party_invites;create policy invites_select on public.party_invites for select to authenticated using(invitee_id=auth.uid() or inviter_id=auth.uid());
drop policy if exists reports_select on public.reports;create policy reports_select on public.reports for select to authenticated using(reporter_id=auth.uid());

insert into storage.buckets(id,name,public) values('party-media','party-media',false) on conflict(id) do nothing;
insert into storage.buckets(id,name,public) values('profile-media','profile-media',false) on conflict(id) do nothing;
